begin;
insert into public.ce_course2_resources(id,data) values
('course2_module6_pdf','{"base64": "", "sha256": "802fb540d56bfee05c828f3c9680f64471c1a7c9d45b24f7ca5f0394d85e4f46", "filename": "CE_HALO_Course2_Module06_OR_Fire_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
('course2_module6_questions','[{"module_id": "course_2_module_6", "question_id": "course_2_module_6_q01", "question_number": 1, "stem": "Which three elements comprise the surgical fire triad?", "choice_a": "Oxidizer, ignition source, and fuel", "choice_b": "Electrocautery, drapes, and alcohol", "choice_c": "Oxygen, water, and heat", "choice_d": "Ignition, combustion, and propagation", "correct_choice": "a", "rationale": "Every surgical fire requires an oxidizer (oxygen and/or nitrous oxide), an ignition source (electrocautery, laser, fiberoptic light, drill), and a fuel (drapes, sponges, alcohol prep, tube, hair). Removing any one element prevents or extinguishes the fire.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q02", "question_number": 2, "stem": "The CRNA''s single most modifiable fire-risk lever is:", "choice_a": "Table height and drape configuration", "choice_b": "Delivered oxygen concentration and use of nitrous oxide", "choice_c": "Choice of induction agent", "choice_d": "Selection of the tracheal tube brand", "correct_choice": "b", "rationale": "The CRNA controls the oxidizer. Keeping open-delivery oxygen at ≤30% in high-risk cases and avoiding nitrous oxide (which supports combustion similarly to oxygen) are the two anesthesia-specific levers with the largest evidence base.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q03", "question_number": 3, "stem": "Which case type is most consistently overrepresented in surgical fire closed-claims analyses?", "choice_a": "Laparoscopic abdominal surgery under general anesthesia", "choice_b": "Cardiac catheterization", "choice_c": "MAC with open oxygen delivery for head, face, or neck procedures", "choice_d": "Elective total knee arthroplasty", "correct_choice": "c", "rationale": "Upper-body procedures (head, face, neck, upper chest) performed under MAC with open oxygen delivery are the dominant closed-claims scenario for surgical fires.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q04", "question_number": 4, "stem": "Electrosurgical devices are the ignition source in approximately what proportion of surgical fires?", "choice_a": "About 90%", "choice_b": "About one-half", "choice_c": "About one-third", "choice_d": "About two-thirds", "correct_choice": "d", "rationale": "Historical ECRI and closed-claims data attribute roughly two-thirds of surgical fires to electrosurgery, with lasers accounting for most of the remainder.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q05", "question_number": 5, "stem": "ChloraPrep contains:", "choice_a": "2% chlorhexidine gluconate with 70% isopropyl alcohol", "choice_b": "Povidone-iodine 10% aqueous", "choice_c": "2% chlorhexidine gluconate in aqueous solution", "choice_d": "Iodine povacrylex with 74% isopropyl alcohol", "correct_choice": "a", "rationale": "ChloraPrep is 2% chlorhexidine gluconate combined with 70% isopropyl alcohol. DuraPrep is the iodine povacrylex/74% isopropanol product.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q06", "question_number": 6, "stem": "Minimum ChloraPrep drying time on hairless skin per the manufacturer IFU is:", "choice_a": "10 minutes", "choice_b": "3 minutes", "choice_c": "30 seconds", "choice_d": "1 minute", "correct_choice": "b", "rationale": "ChloraPrep requires a minimum of 3 minutes to dry on hairless skin and up to 1 hour in hair-bearing areas. Draping or ignition-source activation before drying risks vapor ignition.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q07", "question_number": 7, "stem": "Maximum time that hair-bearing areas may require for ChloraPrep to dry completely is:", "choice_a": "15 minutes", "choice_b": "30 minutes", "choice_c": "Up to 1 hour", "choice_d": "5 minutes", "correct_choice": "c", "rationale": "Hair-bearing areas may require up to 1 hour for alcohol-based preps to dry completely; wet hair remains flammable.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q08", "question_number": 8, "stem": "Which statement about aqueous povidone-iodine is correct?", "choice_a": "It carries the same alcohol-vapor flammability warning as ChloraPrep", "choice_b": "It cannot be used in the OR", "choice_c": "It requires no drying time at all", "choice_d": "It does not carry the same alcohol-vapor flammability warning, but should still be allowed to dry per labeling", "correct_choice": "d", "rationale": "Aqueous povidone-iodine does not carry the alcohol-vapor flammability warning that alcohol-based preps do, but manufacturers typically still specify a drying period before draping.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q09", "question_number": 9, "stem": "In a high-risk case with open oxygen delivery, the widely referenced FiO2 target is:", "choice_a": "≤30% when clinically feasible", "choice_b": "No specific target has been described", "choice_c": "100% for maximum reserve", "choice_d": "50% at all times", "correct_choice": "a", "rationale": "APSF and ASA guidance recommend targeting open-delivery FiO2 at ≤30% during high-risk cases when clinically feasible.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q10", "question_number": 10, "stem": "When higher oxygen concentrations than 30% are clinically necessary during a high-risk case, the recommended alternative is to:", "choice_a": "Continue high-concentration open delivery", "choice_b": "Secure the airway with an LMA or cuffed endotracheal tube", "choice_c": "Increase nitrous oxide instead", "choice_d": "Turn off the pulse oximeter", "correct_choice": "b", "rationale": "If oxygen requirements exceed the 30% open-delivery target, securing the airway (LMA or cuffed ETT) allows delivery of the required FiO2 without an oxidizer-enriched surgical field.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q11", "question_number": 11, "stem": "Why is nitrous oxide avoided in high-fire-risk cases?", "choice_a": "It causes hyperthermia", "choice_b": "It is contraindicated with all inhalational agents", "choice_c": "It supports combustion in a manner similar to oxygen", "choice_d": "It irritates the airway", "correct_choice": "c", "rationale": "Nitrous oxide is an oxidizer that supports combustion similarly to oxygen. A 50/50 oxygen/nitrous oxide environment behaves similarly to a 100% oxygen environment with respect to ignition energy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q12", "question_number": 12, "stem": "Which of the following belongs in the time-out fire risk assessment?", "choice_a": "The circulator''s break schedule", "choice_b": "The patient''s blood type", "choice_c": "The surgeon''s preferred coffee order", "choice_d": "Confirmation that alcohol-based prep is dry, expected use of ignition sources, and current oxidizer status", "correct_choice": "d", "rationale": "A hazard-based time-out fire assessment confirms the presence and status of each triad element: prep-dry status, oxidizer status, and planned ignition source use.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q13", "question_number": 13, "stem": "Modern hazard-based fire risk assessments are preferred over simple low/medium/high scoring because:", "choice_a": "They identify which specific triad elements are present and trigger the specific prevention steps required", "choice_b": "They generate more billing", "choice_c": "They eliminate the need for the surgical time-out", "choice_d": "They are required by CMS as a Never Event", "correct_choice": "a", "rationale": "Hazard-based assessments (per Joint Commission 2024 guidance) identify the specific triad elements in play and trigger the corresponding prevention steps, rather than assigning a single categorical score.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q14", "question_number": 14, "stem": "If a fire occurs in the OR, the CRNA''s priority action is to:", "choice_a": "Push emergency drugs", "choice_b": "Discontinue supplemental oxygen and nitrous oxide and, when indicated, disconnect the breathing circuit", "choice_c": "Extubate the patient immediately", "choice_d": "Call the fire department", "correct_choice": "b", "rationale": "Removing the oxidizer is the anesthesia professional''s immediate action. Discontinuing oxygen and nitrous oxide and disconnecting the circuit when indicated eliminates the CRNA''s element of the triad.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q15", "question_number": 15, "stem": "The correct immediate sequence for a known airway fire is:", "choice_a": "Increase FiO2, then extubate", "choice_b": "Continue ventilation on 100% oxygen to protect against hypoxemia", "choice_c": "Disconnect the circuit and stop all airway gases, remove the tube, pour saline into the airway, then re-establish ventilation", "choice_d": "Call for a code cart before touching the airway", "correct_choice": "c", "rationale": "Airway fires require immediate cessation of gas flow (disconnect the circuit), removal of the involved tube, saline irrigation of the airway to extinguish and cool tissue, and then re-establishment of ventilation on the lowest feasible FiO2.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q16", "question_number": 16, "stem": "For a small fire on the patient or in the surgical field, the preferred initial extinguishing agent is:", "choice_a": "Water from the scrub sink", "choice_b": "A CO2 extinguisher as the first step", "choice_c": "A dry chemical extinguisher", "choice_d": "Saline or sterile water", "correct_choice": "d", "rationale": "Saline or sterile water is the preferred initial extinguishing agent for small fires on the patient or in the airway. A CO2 extinguisher is used if the fire persists or escalates.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q17", "question_number": 17, "stem": "After an airway fire has been extinguished, which of the following is commonly indicated?", "choice_a": "Bronchoscopy to evaluate for retained tube fragments, soot, mucosal injury, and edema", "choice_b": "Head CT", "choice_c": "Cardiac catheterization", "choice_d": "Immediate discharge home", "correct_choice": "a", "rationale": "Bronchoscopy is commonly indicated after airway fires to identify retained tracheal tube fragments, soot, mucosal burns, and edema that may progress to airway compromise.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q18", "question_number": 18, "stem": "In the OR, the RACE model (Rescue, Alarm, Contain, Extinguish/Evacuate):", "choice_a": "Replaces the seven-step surgical fire response for on-patient and airway fires", "choice_b": "Is the broad facility fire framework; the immediate surgical fire response takes priority for on-patient and airway fires", "choice_c": "Is the primary algorithm for airway fires", "choice_d": "Applies only to nursing homes", "correct_choice": "b", "rationale": "RACE is the hospital-wide fire framework. For a fire on the patient or in the airway, the immediate surgical fire response (announce, stop oxidizer, stop ignition, remove fuel, extinguish, re-establish ventilation, debrief) takes priority; the team continues with RACE actions once the immediate patient threat is controlled.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q19", "question_number": 19, "stem": "The PASS mnemonic for fire extinguisher use stands for:", "choice_a": "Push, Aim, Spray, Stop", "choice_b": "Prepare, Alert, Spray, Suppress", "choice_c": "Pull, Aim, Squeeze, Sweep", "choice_d": "Point, Activate, Spray, Stop", "correct_choice": "c", "rationale": "PASS: Pull the pin, Aim at the base of the fire, Squeeze the handle, Sweep from side to side.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q20", "question_number": 20, "stem": "Occlusive drape configurations increase fire risk because they:", "choice_a": "Reduce patient warming", "choice_b": "Increase risk of pressure injury", "choice_c": "Interfere with hemostasis", "choice_d": "Trap oxygen at or near the surgical site, creating an oxidizer-enriched microenvironment", "correct_choice": "d", "rationale": "Occlusive drapes can trap oxygen delivered by nasal cannula or face mask, creating an oxidizer-enriched microenvironment adjacent to the ignition source. Suction scavenging under drapes is one mitigation strategy per local policy.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q21", "question_number": 21, "stem": "For a CO2 laser microlaryngoscopy case, the CRNA-specific safeguards include which of the following?", "choice_a": "Laser-resistant tube, saline-filled cuff (with methylene blue per IFU), FiO2 ≤30% when clinically feasible, and avoidance of N2O", "choice_b": "100% FiO2 and standard PVC tube", "choice_c": "Bipolar cautery only", "choice_d": "Nitrous oxide 70% to keep FiO2 at 30%", "correct_choice": "a", "rationale": "Airway laser cases require a laser-resistant endotracheal tube, saline-filled cuff (methylene blue makes rupture visible, per IFU), the lowest feasible FiO2 (commonly ≤30%), and avoidance of nitrous oxide.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q22", "question_number": 22, "stem": "Which of the following is a correct rule for ignition-device handling?", "choice_a": "The circulator may activate the electrocautery on behalf of the surgeon", "choice_b": "The person activating the ignition device should be the person using it, and inactive devices should remain in a holster or standby mode", "choice_c": "Ignition devices may rest on the surgical drapes when not in active use", "choice_d": "Fiberoptic light cords may be disconnected while the light source is on", "correct_choice": "b", "rationale": "The user activates the ignition device, and inactive devices are placed in a holster or standby mode. Fiberoptic light cords are connected before the light source is activated, and hot tips are kept off drapes and sponges.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "c"], "remaining_choices": ["b", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q23", "question_number": 23, "stem": "The Joint Commission Sentinel Event Alert 68 (2023–2024 update) emphasizes which of the following?", "choice_a": "Eliminating alcohol-based preps in favor of soap and water", "choice_b": "Mandatory 100% FiO2 for all cases", "choice_c": "Hospital-wide fire prevention programs, hazard-based time-out assessment, oxygen management, prep drying-time enforcement, and structured debrief after fires and near misses", "choice_d": "Discontinuing the surgical time-out", "correct_choice": "c", "rationale": "Sentinel Event Alert 68 (2024) emphasizes program-level and case-level actions: written programs, hazard-based time-out assessment, oxygen management, prep drying enforcement, and structured debrief.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q24", "question_number": 24, "stem": "Within the first 10 seconds of a surgical fire, the team''s priority actions include:", "choice_a": "Complete documentation", "choice_b": "Call for consultation", "choice_c": "Prepare for evacuation", "choice_d": "Announce \"fire,\" stop the procedure, discontinue O2 and N2O, and stop the ignition source", "correct_choice": "d", "rationale": "The 0–10 second priorities are announcement, procedure stop, oxidizer discontinuation, and ignition-source deactivation. Fuel removal, extinguishment, and ventilation re-establishment follow in the next 50 seconds.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["a", "b"], "remaining_choices": ["c", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}, {"module_id": "course_2_module_6", "question_id": "course_2_module_6_q25", "question_number": 25, "stem": "After any surgical fire or near miss, best practice is to:", "choice_a": "Document the event thoroughly, report through institutional channels, preserve implicated equipment, and conduct a structured debrief with system-level improvement", "choice_b": "Blame the surgical technologist", "choice_c": "Assign additional cases to the same room to test the equipment", "choice_d": "Move on and forget the event", "correct_choice": "a", "rationale": "Post-event best practice is thorough documentation, institutional reporting, equipment preservation for biomedical review, and a structured debrief that identifies contributing factors and drives system change. Regular fire drills and simulation build the reliable performance needed in the first 60 seconds of a real event.", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "learning_objective_ids": [], "source_ids": [], "source_urls": [], "source_provenance": "provider_reviewed_submitted_content"}]'::jsonb)
on conflict(id) do update set data=excluded.data;
do $$ begin
assert (select encode(sha256(decode(data->>'base64','base64')),'hex')=data->>'sha256' from public.ce_course2_resources where id='course2_module6_pdf'),'PDF hash mismatch';
assert (select released=false from public.ce_course2_catalog where id='1047241'),'Course must remain staged';
end $$;
commit;